#!/bin/bash

# CPU-Bound Benchmarks Script

echo "🚀 Starting CPU benchmarks..."
start_time=$(date +%s)

# Prime number calculation (CPU intensive)
prime_benchmark() {
    echo "🔧 Running prime number calculation benchmark..."
    time=$(timeout 30s bash -c 'count=0; for ((i=2; i<100000; i++)); do is_prime=1; for ((j=2; j*j<=i; j++)); do if (((i%j==0))); then is_prime=0; break; fi; done; if (((is_prime))); then ((count++)); fi; done; echo "Found $count primes"')
    echo "✅ Prime benchmark completed: $time"
}

# Fibonacci sequence calculation
fibonacci_benchmark() {
    echo "🔧 Running Fibonacci sequence benchmark..."
    time=$(timeout 20s bash -c 'fib() { if (( $1 <= 1 )); then echo $1; else fib=$(( $(fib $(( $1 - 1 ))) + $(fib $(( $1 - 2 ))) )); echo $fib; fi; }; result=$(fib 35); echo "Fib(35) = $result"')
    echo "✅ Fibonacci benchmark completed: $time"
}

# Matrix multiplication stress test
matrix_benchmark() {
    echo "🔧 Running matrix multiplication benchmark..."
    time=$(timeout 25s bash -c 'size=200; declare -a matrix1; declare -a matrix2; declare -a result; for ((i=0; i<size*size; i++)); do matrix1[i]=$((RANDOM % 10)); matrix2[i]=$((RANDOM % 10)); done; for ((i=0; i<size; i++)); do for ((j=0; j<size; j++)); do sum=0; for ((k=0; k<size; k++)); do sum=$((sum + ${matrix1[i*size+k]} * ${matrix2[k*size+j]})); done; result[i*size+j]=$sum; done; done; echo "Matrix $size x $size multiplication completed"')
    echo "✅ Matrix benchmark completed: $time"
}

